import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = (value, self.clock() + self.ttl)
            return
        if len(self.cache) == self.capacity:
            self.evict()
        self.cache[key] = (value, self.clock() + self.ttl)

    def get(self, key, default=None):
        if key in self.cache:
            value, expiry = self.cache[key]
            now = self.clock()
            if now >= expiry:
                self.expirations += 1
                self.cache.pop(key)
                self.evictions += 1
                return default
            else:
                self.cache.move_to_end(key)
                self.hits += 1
                return value
        else:
            self.misses += 1
            return default

    def evict(self):
        if self.capacity == 0:
            return
        self.evictions += 1
        while self.cache:
            key, (value, expiry) = self.cache.popitem(last=False)

    def __len__(self):
        count = 0
        now = self.clock()
        for key, (value, expiry) in self.cache.items():
            if now < expiry:
                count += 1
        return count

    def stats(self):
        now = self.clock()
        count = {"hits": self.hits, "misses": self.misses, "evictions": self.evictions, "expirations": self.expirations}
        return count
