import re

def parse_duration(s: str) -> int:
    """Converts a duration string into a total number of seconds.

    - Supported units: `h` (hours), `m` (minutes), `s` (seconds). Units are case-insensitive.
    - Each part is a non-negative integer followed by a unit, e.g. "1h30m", "45s", "2H", "1h 5m 10s", "90m".
    - Whitespace is allowed before, after and between parts.
    - Units must appear in the order h, m, s and each at most once.
    - Raise `ValueError` for empty/blank strings, numbers without a unit, unknown units, decimals, repeated units, or units out of order.
    """
    if not s or not re.match(r"^[a-zA-Z0-9 ]+$", s):
        raise ValueError("Empty or invalid string")

    parts = re.findall(r"(\d+)([hm s]+)", s)
    if not parts:
        raise ValueError("No valid parts found")

    total_seconds = 0
    units = set()

    for count, unit in parts:
        if not count:
            raise ValueError("Missing number")
        try:
            count = int(count)
        except ValueError:
            raise ValueError("Invalid number")

        if unit.lower() == "h":
            if "h" in units:
                raise ValueError("Repeated units")
            total_seconds += count * 3600
            units.add("h")
        elif unit.lower() == "m":
            if "m" in units:
                raise ValueError("Repeated units")
            total_seconds += count * 60
            units.add("m")
        elif unit.lower() == "s":
            if "s" in units:
                raise ValueError("Repeated units")
            total_seconds += count
            units.add("s")
        else:
            raise ValueError(f"Unknown unit: {unit}")

    if any(not u for u in units):
        raise ValueError("Units out of order")

    return total_seconds
