from typing import List

def summarize_ranges(nums: List[int]) -> str:
    """Sorts the numbers and removes duplicates. Then collapse runs of 3 or more consecutive integers into "a..b".
    Numbers in shorter runs (1 or 2 numbers) are listed individually.
    Join everything with "," (no spaces). An empty list returns "".
    """
    if not nums:
        return ""

    nums = sorted(list(set(nums)))
    if len(nums) == 1:
        return str(nums[0])

    result = []
    start = nums[0]
    end = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == end + 1:
            end = nums[i]
        else:
            if start == end:
                result.append(str(start))
            else:
                result.append(f"{start}..{end}")
            start = nums[i]
            end = nums[i]

    if start == end:
        result.append(str(start))
    else:
        result.append(f"{start}..{end}")

    return ",".join(result)
